/* Buildless, browser-local experience. No remote API, account or tracking. */
(() => {
  'use strict';
  const DATA = window.GLOBEA;
  const $ = (s, root = document) => root.querySelector(s);
  const $$ = (s, root = document) => [...root.querySelectorAll(s)];
  const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const norm = s => String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase().trim();
  const money = n => new Intl.NumberFormat('vi-VN', {style:'currency',currency:'VND',maximumFractionDigits:0}).format(n);
  const regions = {north:'Miền Bắc',central:'Miền Trung & Tây Nguyên',south:'Miền Nam'};
  const href = d => `${d.id}.html`;
  const imageSet = id => `assets/${id}-700.jpg 700w, assets/${id}-1200.jpg 1200w, assets/${id}.jpg 2200w`;
  const photo = (id, alt, extra = '') => `<img src="assets/${id}.jpg" srcset="${imageSet(id)}" sizes="${extra.includes('fetchpriority')?'(max-width:720px) 1200px, 100vw':'(max-width:720px) 100vw, 60vw'}" alt="${escape(alt)}" ${extra || 'loading="lazy"'} decoding="async">`;
  const arrow = '<span aria-hidden="true" class="arrow">↗</span>';
  const compass = '<svg class="compass" aria-hidden="true" viewBox="0 0 40 40" fill="none"><circle cx="20" cy="20" r="18.5" stroke="currentColor"/><ellipse cx="20" cy="20" rx="8" ry="18.5" stroke="currentColor"/><path d="M2 20h36M5 10h30M5 30h30" stroke="currentColor"/><path d="m25 14-3 9-8 3 3-9 8-3Z" fill="currentColor"/></svg>';
  const currentId = document.body.dataset.destination;
  const current = DATA.destinations.find(d => d.id === currentId);
  const page = document.body.dataset.page || 'home';
  const state = {query:'', region:'all', interest:'all', savedOnly:false};
  const savedFavorites = read('globea-favorites-v1', []);
  let favorites = (Array.isArray(savedFavorites)?savedFavorites:[]).filter(id => DATA.destinations.some(d => d.id === id));
  let plan = read('globea-plan-v1', null);
  if (!validPlan(plan)) plan = null;
  let selectedDay = 0;
  let activeStep = 0;
  let focusReturn = null;
  let toastTimer;
  let lightboxItems = [];
  let lightboxIndex = 0;

  function read(key, fallback) { try { return JSON.parse(localStorage.getItem(key)) ?? fallback; } catch { return fallback; } }
  function write(key, value) { try { localStorage.setItem(key,JSON.stringify(value)); return true; } catch { toast('Trình duyệt không cho phép lưu. Bạn vẫn có thể in lịch trình.'); return false; } }
  function validPlan(p) {
    if(!p || p.version!==1 || !p.options || !Array.isArray(p.days) || !Array.isArray(p.stay) || !Array.isArray(p.budgetShares)) return false;
    const d=DATA.destinations.find(d=>d.id===p.destination),o=p.options;
    return !!d && Number.isInteger(o.days) && o.days>=1 && o.days<=7 && p.days.length===o.days && Number.isInteger(o.people) && o.people>=1 && o.people<=20 && ['interests','places','foods'].every(k=>Array.isArray(o[k])) && o.foods.every(i=>Number.isInteger(i)&&i>=0&&i<d.foods.length) && ['notes','stay','transport','companion','pace','style','budgetBasis','date'].every(k=>typeof o[k]==='string') && (!o.date||/^\d{4}-\d{2}-\d{2}$/.test(o.date)) && Number.isFinite(o.budget) && p.days.every(day=>typeof day.title==='string'&&Array.isArray(day.slots)&&day.slots.every(s=>['time','label','title','description','area','type'].every(k=>typeof s[k]==='string'))) && p.budgetShares.every(s=>Array.isArray(s)&&typeof s[0]==='string'&&Number.isFinite(s[1]));
  }
  function toast(text) { const el=$('#toast'); el.textContent=text; el.classList.add('visible'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>el.classList.remove('visible'),3600); }
  function button(text, attrs='', cls='button') { return `<button type="button" class="${cls}" ${attrs}>${text}${arrow}</button>`; }
  function brand() { return `<a href="index.html" class="brand" aria-label="GLOBEA · Trang chủ">${compass}<span>GLOBEA<small>EXPLORE THE WORLD, YOUR WAY.</small></span></a>`; }
  function header() { return `<a class="skip-link" href="#main">Đến nội dung chính</a><header class="site-nav ${page==='vietnam'||current?.hero==='editorial'?'on-light':''}" id="site-nav"><div class="nav-inner">${brand()}<nav class="desktop-nav" aria-label="Điều hướng chính"><a href="vietnam.html" ${page==='vietnam'?'aria-current="page"':''}>Việt Nam</a><a href="index.html#diem-den">Điểm đến</a><a href="index.html#trai-nghiem">Trải nghiệm</a><a href="index.html#cau-chuyen">Câu chuyện</a></nav><div class="nav-actions"><button class="saved-toggle" aria-label="Xem điểm đến đã lưu" title="Điểm đến đã lưu">♡ <span class="saved-count">${favorites.length}</span></button><span class="language" lang="vi">VI</span>${button('Thiết kế chuyến đi','data-open-planner','button nav-plan')}<button class="menu-toggle" aria-label="Mở menu" aria-expanded="false" aria-controls="mobile-menu"><span></span><span></span></button></div></div></header><nav id="mobile-menu" aria-label="Điều hướng di động" hidden><small>GLOBEA / VIETNAM EDITION</small><a href="vietnam.html">Việt Nam ${arrow}</a><a href="index.html#diem-den">Điểm đến ${arrow}</a><a href="index.html#trai-nghiem">Trải nghiệm ${arrow}</a><a href="index.html#cau-chuyen">Câu chuyện ${arrow}</a>${button('Lên lịch trình','data-open-planner')}</nav>`; }
  function footer() { return `<footer class="site-footer" id="lien-he"><div class="container footer-top"><div class="footer-about">${brand()}<p>Nhìn gần hơn. Đi sâu hơn.<br>Mỗi nơi chốn, một câu chuyện của riêng bạn.</p><p class="footer-edition">VIETNAM EDITION — VOL. 01</p></div><div><h3>Khám phá</h3><a href="vietnam.html">Việt Nam</a><a href="index.html#diem-den">Tất cả điểm đến</a><a href="index.html#trai-nghiem">Theo sở thích</a><button class="footer-link" data-open-planner>Lên lịch trình</button></div><div><h3>Điểm đến</h3><a href="hoi-an.html">Hội An</a><a href="ha-noi.html">Hà Nội</a><a href="da-lat.html">Đà Lạt</a><a href="ha-long.html">Hạ Long</a></div><div><h3>GLOBEA</h3><a href="index.html#about">Về GLOBEA</a><a href="index.html#cau-chuyen">Những câu chuyện</a><a href="nguon.html">Nguồn & hình ảnh</a><button class="footer-link" data-contact>Liên hệ dự án ${arrow}</button></div></div><div class="container footer-bottom"><span>© 2026 GLOBEA. Explore the World, Your Way.</span><span>Đi nhẹ. Hiểu sâu. Giữ gìn những nơi ta đến.</span><a href="#main" aria-label="Về đầu trang">LÊN ĐẦU TRANG ↑</a></div><div aria-hidden="true" class="footer-giant">GLOBEA</div></footer>`; }
  function card(d, i=0, cls='') { return `<article class="destination-card ${cls}" data-id="${d.id}"><div class="destination-image"><a href="${href(d)}" aria-label="Khám phá ${escape(d.name)}">${photo(d.image,d.name+' · '+d.short)}<span class="image-index">${String(i+1).padStart(2,'0')} / ${regions[d.region].toUpperCase()}</span><span class="image-arrow">${arrow}</span></a><button class="favorite ${favorites.includes(d.id)?'is-saved':''}" data-favorite="${d.id}" aria-label="${favorites.includes(d.id)?'Bỏ lưu':'Lưu'} ${escape(d.name)}" aria-pressed="${favorites.includes(d.id)}">${favorites.includes(d.id)?'♥':'♡'}</button></div><div class="destination-copy"><small>${escape(d.location)} · ${d.duration}</small><a href="${href(d)}"><h3>${d.name} ${arrow}</h3></a><p>${d.short}</p><span class="card-tags">${d.tags.slice(0,2).map(t=>DATA.interests.find(x=>x[0]===t)[1]).join(' / ')}</span><a class="text-link card-detail" href="${href(d)}">Khám phá điểm đến ${arrow}</a></div></article>`; }
  function home() {
    return `<section class="home-hero" aria-labelledby="hero-title"><div class="hero-image">${photo('halong-bay','Mặt nước phản chiếu những đảo đá vôi trên vịnh Hạ Long','fetchpriority="high" loading="eager"')}</div><div class="hero-shade"></div><div class="hero-topline"><span>MỖI NƠI CHỐN, MỘT CÂU CHUYỆN</span><span>VOL. 01 — VIETNAM</span></div><div class="container hero-copy"><div class="eyebrow light entrance">ĐI XA HƠN. CẢM NHẬN NHIỀU HƠN.</div><h1 id="hero-title"><span class="hero-line">Thế giới rộng lớn.</span><span class="hero-line"><em>Bắt đầu từ Việt Nam.</em></span></h1><div class="hero-description entrance"><p>Những miền đất quen. Những góc nhìn mới.<br>Và một hành trình chỉ thuộc về bạn.</p><a class="round-link" href="vietnam.html" aria-label="Khám phá Việt Nam">${arrow}</a></div></div><div class="hero-side"><span class="hero-seal">${compass}</span>TRAVEL DEEPER<br>FEEL MORE</div><div class="container hero-bottom"><form class="hero-search" id="hero-search" role="search"><label class="search-destination"><span aria-hidden="true" class="field-symbol">⌖</span><span><small>ĐIỂM ĐẾN CỦA BẠN</small><input type="search" name="destination" placeholder="Bạn muốn đi đâu?" aria-label="Tìm điểm đến" list="destination-suggestions" autocomplete="off"><datalist id="destination-suggestions">${DATA.destinations.map(d=>`<option value="${d.name}"></option>`).join('')}</datalist></span></label><label><span aria-hidden="true" class="field-symbol">◷</span><span><small>NHỊP ĐIỆU</small><select name="pace" aria-label="Nhịp điệu chuyến đi"><option value="all">Theo cách của bạn</option value="relax">Thư thả & nghỉ dưỡng</option><option value="adventure">Khám phá & phiêu lưu</option></select></span></label><label><span aria-hidden="true" class="field-symbol">✳</span><span><small>CẢM HỨNG</small><select name="interest" aria-label="Sở thích du lịch"><option value="all">Mọi trải nghiệm</option>${DATA.interests.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></span></label><button class="search-submit" type="submit">Khám phá ${arrow}</button></form><div class="hero-bottom-line"><span><i class="live-dot"></i> HẠ LONG, VIỆT NAM <span class="coordinates">/ 20.9101° N 107.1839° E</span></span><a href="#about">CUỘN ĐỂ CẢM NHẬN <span aria-hidden="true">↓</span></a></div></div></section>
    <section class="intro-section container section-space" id="about"><div class="intro-heading reveal"><span class="eyebrow">01 / A COUNTRY TO FEEL</span><h2>Quen thuộc.<br>Mà vẫn <em>ngỡ ngàng.</em></h2><span class="little-compass" aria-hidden="true">✳</span></div><div class="intro-copy reveal"><p class="lead">Một dải đất. Vô vàn sắc thái.<br>Một Việt Nam chưa bao giờ thôi khiến ta muốn lên đường.</p><p>Từ núi đá giữa mây trời đến phố cổ màu nắng. Từ một tô phở buổi sớm đến câu chuyện bên hiên nhà. GLOBEA mời bạn nhìn gần hơn, ở lại lâu hơn và tìm thấy cách khám phá của riêng mình.</p><a href="vietnam.html" class="text-link">Mở cuốn cẩm nang Việt Nam ${arrow}</a></div><figure class="intro-image reveal">${photo('hoian-alley','Một ngõ nhỏ với tường vàng và cửa xanh ở Hội An')}<figcaption>MỘT GÓC HỘI AN / NHỮNG ĐIỀU BÌNH DỊ</figcaption></figure></section>
    <section class="destinations-section section-space" id="diem-den"><div class="container"><div class="section-heading reveal"><div><span class="eyebrow">02 / THE PLACES WE LOVE</span><h2>Chọn một nơi.<br><em>Bắt đầu một câu chuyện.</em></h2></div><p>Tám điểm đến, tám nhịp sống.<br>Bạn muốn viết chương đầu tiên ở đâu?</p></div>${filters()}<div id="destination-results" class="destination-grid" aria-live="polite"></div><p id="results-count" class="results-count"></p><div class="destination-end"><span>KHÔNG CẦN ĐI HẾT. CHỈ CẦN ĐI THẬT SÂU.</span><a class="text-link" href="vietnam.html">Khám phá ba miền ${arrow}</a></div></div></section>
    <section class="interests-section container section-space" id="trai-nghiem"><div class="interest-visual reveal"><div class="interest-photo">${photo('dalat-pines','Rừng thông ở Đà Lạt','id="interest-image" loading="lazy"')}</div><span class="interest-photo-label" id="interest-photo-label">ĐÀ LẠT / NATURE & STILLNESS</span><div class="interest-note"><span>✳</span><p>Đi theo điều<br><em>khiến bạn rung động.</em></p></div></div><div class="interest-copy"><span class="eyebrow reveal">03 / FOLLOW YOUR CURIOSITY</span><h2 class="reveal">Bạn đi tìm<br><em>điều gì?</em></h2><div class="interest-rows" role="tablist" aria-label="Khám phá theo sở thích">${DATA.interests.map(([v,t],i)=>`<button role="tab" aria-selected="${i===0}" aria-controls="interest-matches" id="interest-${v}" data-interest="${v}" class="${i===0?'active':''}"><span>0${i+1}</span>${t}${arrow}</button>`).join('')}</div><div id="interest-matches" role="tabpanel" aria-labelledby="interest-nature" tabindex="0"></div></div></section>
    <section class="story-full" id="cau-chuyen"><div class="story-photo">${photo('hoian-street','Người dân và những mái nhà cổ trên đường phố Hội An')}</div><div class="story-overlay"></div><div class="container story-inner"><span class="eyebrow light reveal">04 / MORE THAN A DESTINATION</span><h2 class="reveal">Không chỉ là nơi đến.<br><em>Là những điều ở lại.</em></h2><div class="story-bottom"><p class="reveal">Một lời chào trong ngõ nhỏ. Một món ăn được nấu bằng ký ức. Một người kể chuyện chưa từng gặp. Việt Nam đẹp nhất khi bạn dành thời gian để lắng nghe.</p><a class="button button-light" href="hoi-an.html#lich-su">Lắng nghe Hội An ${arrow}</a></div><div class="story-credit">HỘI AN, VIỆT NAM <span>THE HUMAN SIDE OF TRAVEL</span></div></div></section>
    ${plannerInvite()}<section class="closing container"><span class="eyebrow reveal">THE NEXT CHAPTER IS YOURS</span><h2 class="reveal">Đi một nơi mới.<br><em>Mang về một phần mình.</em></h2><a href="#diem-den" class="text-link">Tìm cảm hứng cho chuyến đi ${arrow}</a></section>`;
  }
  function filters() { return `<div class="destination-tools"><div class="filter-tabs" role="group" aria-label="Lọc theo miền"><button data-region="all" class="active" aria-pressed="true">Tất cả</button><button data-region="north" aria-pressed="false">Miền Bắc</button><button data-region="central" aria-pressed="false">Miền Trung</button><button data-region="south" aria-pressed="false">Miền Nam</button></div><label class="filter-search"><span aria-hidden="true">⌕</span><input type="search" id="destination-query" aria-label="Lọc tên điểm đến" placeholder="Tìm một miền đất…"></label><button class="filter-saved" aria-pressed="false">♡ Đã lưu <span class="saved-count">${favorites.length}</span></button></div><div id="active-search" hidden></div>`; }
  function plannerInvite() { return `<section class="planner-invite section-space" id="len-lich-trinh"><div class="container planner-invite-grid"><div class="reveal"><span class="eyebrow">05 / YOUR JOURNEY, BEAUTIFULLY PLANNED</span><h2>Một hành trình.<br><em>Đúng chất bạn.</em></h2><p>Bớt thời gian sắp xếp. Thêm thời gian tận hưởng. Chọn điều mình thích, để GLOBEA gợi ý một chuyến đi vừa vặn với nhịp sống của bạn.</p>${button('Thiết kế chuyến đi của bạn','data-open-planner')}<span class="small-note">Không cần tài khoản. Lưu ngay trên trình duyệt của bạn.</span></div><div class="plan-preview reveal" data-tilt><div class="preview-top"><span>GLOBEA / TRAVEL NOTES</span><span>✳</span></div><div class="preview-main">${photo('hoian-alley','Ngõ vàng Hội An')}<div><small>VIỆT NAM · 3 NGÀY</small><h3>Hẹn một ngày<br><em>ở Hội An.</em></h3><span>Văn hóa / Ẩm thực / Biển</span></div></div><div class="preview-day"><b>01</b><div><strong>Chạm vào di sản</strong><span>Phố cổ · Chùa Cầu · Cao lầu</span></div><span>↗</span></div><div class="preview-day"><b>02</b><div><strong>Nhịp sống địa phương</strong><span>Trà Quế · Thanh Hà · Mì Quảng</span></div><span>↗</span></div><div class="preview-day"><b>03</b><div><strong>Một ngày thật chậm</strong><span>An Bàng · Cà phê · Gió biển</span></div><span>↗</span></div><button data-open-planner class="preview-bottom">BIẾN CẢM HỨNG THÀNH HÀNH TRÌNH ${arrow}</button><span class="preview-paper" aria-hidden="true"></span></div></div></section>`; }
  function vietnam() { return `<section class="vietnam-hero container"><div class="vietnam-title"><span class="eyebrow entrance">GLOBEA COUNTRY GUIDE / 001</span><h1>Việt Nam<span class="gold">.</span></h1><div class="vietnam-sub"><p>Một đất nước.<br><em>Vạn điều để thương.</em></p><span>08 ĐIỂM ĐẾN<br>03 MIỀN CẢM HỨNG</span></div></div><div class="vietnam-hero-image">${photo('ninh-binh','Dòng sông uốn giữa núi đá và đồng xanh Ninh Bình','fetchpriority="high" loading="eager"')}<span>NINH BÌNH / THE BEAUTY OF SLOWNESS</span></div></section><section class="country-intro container section-space"><span class="eyebrow reveal">MỘT VIỆT NAM, NHIỀU SẮC THÁI</span><p class="country-statement reveal">Có núi cao để thấy mình nhỏ bé.<br>Có những phố xưa để thấy lòng <em>gần lại.</em><br>Và có những người lạ khiến ta thấy như về nhà.</p><div class="country-intro-bottom"><span>THIÊN NHIÊN / VĂN HÓA / CON NGƯỜI</span><p>Từ đồng bằng sông Hồng đến cao nguyên và những hòn đảo phía nam, mỗi vùng đất có khí hậu, hương vị và nếp sống riêng. Bắt đầu từ một miền, dành thời gian cho những điều nhỏ bé.</p></div></section>
    <section class="region-section section-space" id="ba-mien"><div class="container region-layout"><div class="region-intro"><span class="eyebrow">01 / THREE REGIONS, ENDLESS STORIES</span><h2>Đi dọc<br><em>miền thương nhớ.</em></h2><p>Chọn một miền để bắt đầu khám phá.</p><div class="region-route" aria-label="Hành trình ba miền Việt Nam"><span class="route-line" aria-hidden="true"></span>${[['north','01','Miền Bắc','Di sản & những kỳ quan'],['central','02','Miền Trung','Phố cổ & cao nguyên'],['south','03','Miền Nam','Nhịp phố & biển đảo']].map(([v,n,t,s],i)=>`<button data-country-region="${v}" class="${i===0?'active':''}" aria-pressed="${i===0}"><span>${n}</span><div><strong>${t}</strong><small>${s}</small></div>${arrow}</button>`).join('')}</div></div><div id="region-results" aria-live="polite"></div></div></section>
    <section class="country-food container section-space"><div class="section-heading reveal"><div><span class="eyebrow">02 / A TASTE OF VIETNAM</span><h2>Một đất nước.<br><em>Muôn vị thương.</em></h2></div><p>Để hiểu một nơi, hãy bắt đầu<br>bằng một bữa ăn cùng hương vị bản địa.</p></div><div class="food-regions">${[['01','Miền Bắc','Tinh tế & hài hòa','Phở Hà Nội, bún chả, bánh cuốn. Những món ăn giản dị với nhiều lớp hương vị.','ha-noi'],['02','Miền Trung','Đậm đà & nhiều sắc thái','Bún bò Huế, cao lầu Hội An, mì Quảng. Mỗi địa phương là một câu chuyện riêng.','hue'],['03','Miền Nam','Phóng khoáng & gần gũi','Cơm tấm, hủ tiếu và sản vật biển đảo. Một cuộc gặp đầy cảm hứng giữa các nền văn hóa.','ho-chi-minh']].map(([n,t,h,p,id])=>`<a class="food-region reveal" href="${id}.html#am-thuc"><span>${n} / ${t.toUpperCase()}</span><h3>${h}</h3><p>${p}</p><span class="text-link">Theo dấu hương vị ${arrow}</span></a>`).join('')}</div></section>
    <section class="country-story"><div>${photo('hue-citadel','Kiến trúc Đại Nội Huế dưới bầu trời xanh')}</div><div class="country-story-copy"><span class="eyebrow">03 / TIMELESS VIETNAM</span><h2>Những điều xưa.<br><em>Vẫn đang sống.</em></h2><p>Di sản không chỉ nằm sau những cánh cửa bảo tàng. Nó hiện diện trong một mái nhà cổ, một nghề thủ công, một cách nấu ăn được truyền lại qua nhiều thế hệ.</p><a class="text-link" href="hue.html#lich-su">Mở câu chuyện cố đô ${arrow}</a></div></section>
    <section class="country-practical container section-space"><div><span class="eyebrow">04 / BEFORE YOU GO</span><h2>Đi đúng lúc.<br><em>Đi thật nhẹ.</em></h2><p>Khí hậu thay đổi theo vùng. Hãy chọn mùa cho nơi bạn muốn đến và giữ lịch trình linh hoạt.</p></div><div>${accordion('Mùa nào dành cho bạn?','Miền Bắc có bốn mùa; mùa xuân và thu thường dễ chịu. Miền Trung có mùa mưa thay đổi theo khu vực. Miền Nam ấm quanh năm với mùa khô và mùa mưa. Luôn kiểm tra dự báo gần ngày khởi hành.',true)}${accordion('Đi giữa các miền','Kết hợp máy bay, tàu hỏa hoặc xe khách tùy khoảng cách. Đừng ghép quá nhiều vùng trong một chuyến ngắn: thời gian di chuyển cũng là một phần của hành trình.')}${accordion('Tôn trọng nơi mình đến','Ăn mặc phù hợp ở nơi thờ tự, xin phép trước khi chụp người dân, dùng dịch vụ địa phương và mang theo bình nước dùng lại.')}${accordion('Một lịch trình vừa đủ','3 ngày cho một thành phố. 5–7 ngày cho một vùng. Nếu đi xuyên Việt, hãy dành thêm thời gian và chừa khoảng trống cho nghỉ ngơi.')}</div></section>
    <section class="journey-suggestions container"><div class="section-heading"><div><span class="eyebrow">05 / A LITTLE INSPIRATION</span><h2>Những ngày <em>đáng nhớ.</em></h2></div></div><div class="journey-list">${[['ha-noi','03','Hà Nội, từng nếp phố','Văn hóa & ẩm thực'],['hoi-an','03','Hội An, thật chậm','Di sản & biển'],['da-lat','03','Đà Lạt, giữa ngàn thông','Thiên nhiên & cà phê']].map(([id,n,t,s])=>`<button data-open-planner data-planner-destination="${id}"><span>${n}<small>NGÀY</small></span><div><h3>${t}</h3><p>${s}</p></div>${arrow}</button>`).join('')}</div></section>${plannerInvite()}`; }
  function accordion(title, content, open=false) { return `<details ${open?'open':''}><summary>${title}<span aria-hidden="true">+</span></summary><p>${content}</p></details>`; }
  function destination(d) {
    const full = d.hero==='cinematic'||d.hero==='atmospheric';
    return `<section class="place-hero hero-${d.hero}" style="--place-accent:${d.accent}"><div class="place-hero-image">${photo(d.image,d.name+' · '+d.short,'fetchpriority="high" loading="eager"')}</div>${full?'<div class="place-hero-shade"></div>':''}<div class="place-breadcrumb"><a href="index.html">GLOBEA</a><span>/</span><a href="vietnam.html">VIỆT NAM</a><span>/</span><span>${d.name.toUpperCase()}</span></div><div class="place-hero-copy"><span class="eyebrow ${full?'light':''}">${d.edition}</span><h1>${d.name}<span>.</span></h1><p>${d.tagline}</p><a href="#tong-quan" class="place-scroll">Khám phá câu chuyện <span aria-hidden="true">↓</span></a></div><span class="place-coordinates">${d.coordinates}</span><span class="place-hero-edition">VIETNAM / GLOBEA JOURNAL</span></section>
    <div class="place-facts container"><div><small>MIỀN ĐẤT</small><strong>${d.location}</strong></div><div><small>THỜI GIAN GỢI Ý</small><strong>${d.duration}</strong></div><div><small>THỜI ĐIỂM THAM KHẢO</small><strong>${d.season}</strong></div><div><small>THEO CÁCH CỦA BẠN</small><button data-favorite="${d.id}" class="inline-favorite" aria-pressed="${favorites.includes(d.id)}">${favorites.includes(d.id)?'♥ Đã lưu điểm đến':'♡ Lưu điểm đến'}</button></div></div><nav class="place-subnav" aria-label="Nội dung ${d.name}"><div class="container"><a href="#tong-quan">Tổng quan</a><a href="#lich-su">Câu chuyện</a><a href="#noi-bat">Khám phá</a><a href="#am-thuc">Ẩm thực</a><a href="#luu-tru">Lưu trú</a><a href="#meo-hay">Cẩm nang</a></div></nav>
    <section class="place-overview container section-space" id="tong-quan"><div class="reveal"><span class="eyebrow">01 / THE SPIRIT OF ${d.id.toUpperCase().replaceAll('-',' ')}</span><h2>Chạm vào<br><em>một miền cảm xúc.</em></h2></div><div class="reveal"><p class="lead">${d.intro}</p><p class="overview-special">${d.special}</p>${button('Thêm vào hành trình','data-open-planner','text-link')}</div></section>
    <section class="history-section" id="lich-su"><div class="container history-grid"><figure class="history-image reveal"><button class="gallery-trigger" data-gallery="${d.id}" data-index="0" aria-label="Mở ảnh ${d.name}">${photo(d.gallery[0],d.name+' · Một góc nhìn khác')}<span class="gallery-enlarge">Xem ảnh lớn ${arrow}</span></button><figcaption>${d.name.toUpperCase()} / STORIES THAT STAY</figcaption></figure><div class="history-copy reveal"><span class="eyebrow">02 / A LITTLE HISTORY</span><h2>Thời gian đi qua.<br><em>Câu chuyện ở lại.</em></h2><p>${d.history}</p><div class="history-tabs" role="tablist" aria-label="Dấu mốc lịch sử">${d.timeline.map(([year],i)=>`<button role="tab" id="history-tab-${i}" aria-selected="${i===0}" aria-controls="history-panel" data-history="${i}" class="${i===0?'active':''}">${year}</button>`).join('')}</div><div class="history-panel" id="history-panel" role="tabpanel" tabindex="0" aria-labelledby="history-tab-0"><h3>${d.timeline[0][1]}</h3><p>${d.timeline[0][2]}</p></div><a class="source-link" href="${d.source}" target="_blank" rel="noopener">Nguồn: ${d.sourceLabel} ↗</a></div></div></section>
    <section class="places-section container section-space" id="noi-bat"><div class="section-heading reveal"><div><span class="eyebrow">03 / WORTH YOUR TIME</span><h2>Những nơi<br><em>đáng dừng chân.</em></h2></div><p>Chọn một vài điểm bạn thích.<br>Thêm vào lịch trình và khám phá theo nhịp riêng.</p></div><div class="places-editorial"><div class="place-sticky reveal"><figure><button class="gallery-trigger" data-gallery="${d.id}" data-index="${Math.min(1,d.gallery.length-1)}" aria-label="Xem ảnh ${d.name}">${photo(d.gallery[Math.min(1,d.gallery.length-1)],d.name+' · Phong cảnh và cuộc sống')}<span class="gallery-enlarge">MỞ KHUNG HÌNH ${arrow}</span></button><figcaption>${d.quote}</figcaption></figure></div><div class="place-list">${d.places.map(([name,loc,desc,tags],i)=>`<article class="place-row reveal"><span class="place-number">${String(i+1).padStart(2,'0')}</span><div><small>${loc}</small><h3>${name}</h3><p>${desc}</p><a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(name+' '+d.name+' Việt Nam')}" target="_blank" rel="noopener" class="map-link">Xem bản đồ ↗</a></div><button class="add-place" data-add-place="${i}" aria-label="Thêm ${escape(name)} vào lịch trình" title="Thêm vào lịch trình">+</button></article>`).join('')}</div></div></section>
    <section class="food-section" id="am-thuc"><div class="container"><div class="section-heading reveal"><div><span class="eyebrow light">04 / TASTE THE PLACE</span><h2>Hương vị<br><em>của miền nhớ.</em></h2></div><p>Không cần một địa chỉ cầu kỳ.<br>Đôi khi, một món ăn đủ để nhớ cả chuyến đi.</p></div><div class="food-list">${d.foods.map(([name,desc],i)=>`<article class="reveal"><span>0${i+1}</span><h3>${name}</h3><p>${desc}</p><button data-add-food="${i}" class="text-link">Muốn thử ${arrow}</button></article>`).join('')}</div></div></section>
    <section class="stay-section container section-space" id="luu-tru"><div class="reveal"><span class="eyebrow">05 / STAY A LITTLE LONGER</span><h2>Ở lại.<br><em>Để thấy gần hơn.</em></h2><p>Chọn khu vực trước, chọn chỗ ở sau. Cân nhắc nhịp đi, phương tiện và khoảng cách đến những nơi bạn muốn khám phá.</p><span class="small-note">Gợi ý khu vực và loại hình; không phải danh sách cơ sở được đặt chỗ.</span></div><div class="reveal">${d.stays.map(([name,desc],i)=>accordion(name,desc,i===0)).join('')}</div></section>
    ${d.gallery.length>1?`<section class="place-gallery container"><div class="section-heading"><span class="eyebrow">A FEW FRAMES TO REMEMBER</span><span>NHẤN ĐỂ XEM ẢNH LỚN ↗</span></div><div class="gallery-grid">${d.gallery.map((img,i)=>`<button class="gallery-trigger reveal" data-gallery="${d.id}" data-index="${i}" aria-label="Mở ảnh ${i+1} của ${d.name}">${photo(img,d.name+' · Khung hình '+(i+1))}<span class="gallery-enlarge">0${i+1} / ${d.name.toUpperCase()} ${arrow}</span></button>`).join('')}</div></section>`:''}
    <section class="tips-section section-space" id="meo-hay"><div class="container"><div class="section-heading reveal"><div><span class="eyebrow">06 / LITTLE THINGS TO KNOW</span><h2>Chuẩn bị ít.<br><em>Tận hưởng nhiều.</em></h2></div><p>Thông tin thời tiết, vé và giờ mở cửa có thể thay đổi. Kiểm tra kênh chính thức gần ngày đi.</p></div><div class="tips-grid">${d.tips.map(([t,p],i)=>`<article class="reveal"><span>0${i+1} / TRAVEL THOUGHTFULLY</span><h3>${t}</h3><p>${p}</p></article>`).join('')}</div></div></section><section class="place-ending container"><span class="eyebrow">YOUR NEXT CHAPTER</span><blockquote>“${d.quote}”</blockquote>${button('Hẹn một chuyến đến '+d.name,'data-open-planner')}</section><section class="related container"><div class="section-heading"><h2>Vẫn còn những miền <em>muốn đến.</em></h2><a href="vietnam.html" class="text-link">Xem Việt Nam ${arrow}</a></div><div class="related-grid">${DATA.destinations.filter(x=>x.id!==d.id).slice(0,3).map((x,i)=>card(x,i)).join('')}</div></section>`;
  }
  function sources() { return `<section class="source-page container section-space"><span class="eyebrow">GLOBEA / EDITORIAL NOTES</span><h1>Nguồn &<br><em>những lời cảm ơn.</em></h1><p class="lead">Những câu chuyện có căn cứ. Những khung hình có nguồn gốc.</p><h2>Nội dung điểm đến</h2><p>Nội dung được biên tập tham khảo cổng thông tin du lịch Việt Nam và hồ sơ UNESCO. Thời gian khám phá là gợi ý biên tập. Không hiển thị giá vé, giá phòng, xếp hạng hoặc giờ mở cửa chưa xác minh.</p><ul>${DATA.destinations.map(d=>`<li><a href="${d.source}" target="_blank" rel="noopener">${d.sourceLabel} ↗</a></li>`).join('')}</ul><h2>Hình ảnh</h2><p>Các ảnh trong phiên bản Việt Nam được tải về từ Pexels, sử dụng theo <a href="https://www.pexels.com/license/" target="_blank" rel="noopener">Pexels License</a>. Tên ảnh và đường dẫn nguồn được lưu trong assets/photo-credits.json.</p><ul>${[['ninh-binh',30280829],['dalat-mist',30317696],['dalat-pines',36720811],['hoian-river',33501218],['hoian-street',14022164],['hoian-alley',26087000],['hanoi-lake',20498719],['hanoi-bridge',36399804],['hanoi-quiet',29827506],['hue-citadel',13971217],['halong-bay',6876808],['halong-boats',6876855],['phuquoc-beach',4603354],['saigon-skyline',18099746]].map(([name,id])=>`<li><a href="https://www.pexels.com/photo/${id}/" target="_blank" rel="noopener">${name} · Pexels ${id} ↗</a></li>`).join('')}</ul><h2>Smart Trip Planner</h2><p>Lịch trình được gợi ý bằng quy tắc từ dữ liệu địa điểm có sẵn. Công cụ không sử dụng AI, không đặt dịch vụ và không xác nhận tình trạng hoạt động. Ngân sách được phân bổ từ số tiền bạn nhập, không phải ước tính giá thị trường. Dữ liệu lưu trên trình duyệt thiết bị hiện tại.</p><h2 id="thong-tin-lien-he">Liên hệ dự án</h2><p>GLOBEA là dự án giao diện du lịch. Hiện chưa cung cấp kênh liên hệ hoặc dịch vụ đặt tour. Trang này là thông tin liên hệ chính thức của bản trình diễn.</p><h2>Typography</h2><p>Instrument Serif và Manrope, được lưu cục bộ từ Google Fonts. Xem giấy phép trong thư mục assets/fonts.</p><a href="index.html" class="text-link">Về trang chủ ${arrow}</a></section>`; }

  function overlays() { return `<button class="planner-tab" data-open-planner aria-controls="planner" aria-haspopup="dialog"><span aria-hidden="true">←</span><span>Lên lịch trình</span><span aria-hidden="true">✳</span></button><dialog class="planner-drawer" id="planner" aria-labelledby="planner-title"><div class="drawer-head"><div><span class="eyebrow">YOUR JOURNEY, YOUR WAY</span><h2 id="planner-title">Thiết kế <em>chuyến đi.</em></h2><p id="planner-context">${current?current.name:'Việt Nam'} / GLOBEA TRAVEL NOTES</p></div><button class="icon-button" data-close-planner aria-label="Đóng lịch trình">×</button></div><div class="drawer-content"><div class="planner-stepper" aria-label="Tiến độ thiết kế"><span class="active">01 <small>Chuyến đi</small></span><span>02 <small>Điều bạn thích</small></span><span>03 <small>Cách bạn đi</small></span></div><form id="planner-form"><section class="form-step" data-step="0"><h3>Bắt đầu từ một nơi muốn đến.</h3><label class="form-field">Điểm đến<select name="destination" id="planner-destination">${DATA.destinations.map(d=>`<option value="${d.id}" ${(current?.id||'hoi-an')===d.id?'selected':''}>${d.name}</option>`).join('')}</select></label><div class="form-grid"><label class="form-field">Số ngày<input name="days" type="number" min="1" max="7" value="3" required inputmode="numeric"><small>Từ 1 đến 7 ngày</small></label><label class="form-field"><span>Ngày bắt đầu <small>(tùy chọn)</small></span><input name="date" type="date"></label></div><div class="form-grid"><label class="form-field">Số người<input name="people" type="number" min="1" max="20" value="2" required inputmode="numeric"></label><label class="form-field">Bạn đồng hành<select name="companion"><option value="couple">Cặp đôi</option><option value="solo">Một mình</option><option value="friends">Bạn bè</option><option value="family">Gia đình</option></select></label></div><div class="form-inspiration">${photo(current?.image||'hoian-alley',current?.name||'Hội An','id="planner-photo" loading="lazy"')}<p>Một chuyến đi đẹp<br>bắt đầu từ <em>bạn.</em></p></div><button type="button" id="load-plan" class="text-link" ${plan?'':'hidden'}>Mở lịch trình đã lưu ${arrow}</button></section><section class="form-step" data-step="1" hidden><h3>Những điều khiến bạn rung động.</h3><fieldset><legend>Sở thích <small>Chọn nhiều</small></legend><div class="chips">${DATA.interests.map(([v,t],i)=>`<label><input type="checkbox" name="interests" value="${v}" ${i<2?'checked':''}><span>${t}</span></label>`).join('')}</div></fieldset><fieldset><legend>Nhất định muốn ghé <small>Tùy chọn</small></legend><div class="chips place-chips" id="planner-places"></div></fieldset><fieldset><legend>Hương vị muốn thử <small>Tùy chọn</small></legend><div class="chips" id="planner-foods"></div></fieldset></section><section class="form-step" data-step="2" hidden><h3>Một hành trình vừa vặn.</h3><div class="form-grid"><label class="form-field">Ngân sách (VNĐ)<input type="number" name="budget" min="0" max="1000000000" step="1000" value="6000000" inputmode="numeric"><small>Để trống nếu chưa quyết định</small></label><label class="form-field">Cách tính<select name="budgetBasis"><option value="total">Tổng cả nhóm</option><option value="person">Mỗi người</option></select></label></div><div class="form-grid"><label class="form-field">Phong cách<select name="style"><option value="budget">Tiết kiệm</option><option value="balanced" selected>Cân bằng</option><option value="comfortable">Thoải mái</option><option value="luxury">Cao cấp</option></select></label><label class="form-field">Lưu trú<select name="stay"><option>Homestay</option><option>Hostel</option><option>Khách sạn</option><option>Resort</option></select></label></div><label class="form-field">Di chuyển ưu tiên<select name="transport"><option>Đi bộ + taxi</option><option>Xe đạp + taxi</option><option>Xe máy</option><option>Ô tô có tài xế</option><option>Phương tiện công cộng</option></select></label><fieldset><legend>Nhịp độ hành trình</legend><div class="chips segmented">${[['slow','Thư giãn'],['balanced','Cân bằng'],['active','Khám phá nhiều']].map(([v,t])=>`<label><input type="radio" name="pace" value="${v}" ${v==='balanced'?'checked':''}><span>${t}</span></label>`).join('')}</div></fieldset><label class="form-field">Yêu cầu riêng<textarea name="notes" rows="3" maxlength="500" placeholder="Ví dụ: đi cùng trẻ nhỏ, muốn nghỉ trưa dài…"></textarea></label><p class="form-note">Gợi ý từ dữ liệu GLOBEA. Yêu cầu riêng được ghi lại để bạn tự điều chỉnh; không thay thế kiểm tra thực tế.</p></section><p id="form-error" role="alert" hidden></p></form><section id="planner-result" hidden></section></div><div class="drawer-foot"><button type="button" id="planner-back" class="text-link" hidden>← Quay lại</button><button type="button" id="planner-next" class="button">Tiếp tục ${arrow}</button><button type="submit" form="planner-form" id="planner-generate" class="button" hidden>Tạo lịch trình ${arrow}</button></div></dialog><dialog id="lightbox" aria-label="Bộ ảnh điểm đến"><button class="lightbox-close icon-button" aria-label="Đóng ảnh">×</button><button class="lightbox-prev icon-button" aria-label="Ảnh trước">←</button><figure><img src="assets/halong-bay.jpg" alt=""><figcaption></figcaption></figure><button class="lightbox-next icon-button" aria-label="Ảnh tiếp theo">→</button></dialog><div id="toast" role="status" aria-live="polite"></div><button id="back-top" class="back-top" aria-label="Về đầu trang">↑</button><div id="print-plan"></div>`; }

  document.body.insertAdjacentHTML('afterbegin', header());
  $('#main').innerHTML = page==='home'?home():page==='vietnam'?vietnam():page==='sources'?sources():current?destination(current):home();
  document.body.insertAdjacentHTML('beforeend', footer()+overlays());
  const dialog = $('#planner');
  const form = $('#planner-form');
  const lightbox = $('#lightbox');
  const reduced = matchMedia('(prefers-reduced-motion: reduce)');
  refreshPlannerChoices();
  if(page==='home') { renderDestinations(); setInterest('nature'); }
  if(page==='vietnam') renderRegion('north');

  function renderDestinations() {
    const matches=DATA.destinations.filter(d=>(state.region==='all'||d.region===state.region)&&(state.interest==='all'||d.tags.includes(state.interest))&&(!state.savedOnly||favorites.includes(d.id))&&norm(d.name+' '+d.location+' '+d.short).includes(norm(state.query)));
    const grid=$('#destination-results'); if(!grid)return;
    grid.innerHTML=matches.length?matches.map((d,i)=>card(d,i,matches.length===8&&i===0?'featured':'')).join(''):`<div class="empty-state"><span>⌖</span><h3>Chưa tìm thấy miền đất ấy.</h3><p>Thử một tên khác hoặc mở lại tất cả điểm đến.</p>${button('Xem tất cả','data-clear-filters','text-link')}</div>`;
    grid.classList.toggle('is-filtered',matches.length!==8);
    $('#results-count').textContent=`${matches.length.toString().padStart(2,'0')} điểm đến${state.savedOnly?' đã lưu':''}${state.query?' cho “'+state.query+'”':''}`;
    const active=$('#active-search'); active.hidden=state.interest==='all'; active.innerHTML=state.interest==='all'?'':`<span>Trải nghiệm: ${DATA.interests.find(x=>x[0]===state.interest)?.[1]||''}</span><button data-clear-interest aria-label="Bỏ lọc sở thích">×</button>`;
    $$('[data-region]').forEach(b=>{b.classList.toggle('active',b.dataset.region===state.region);b.setAttribute('aria-pressed',b.dataset.region===state.region)});
    $('.filter-saved').setAttribute('aria-pressed',state.savedOnly);
  }
  function renderRegion(region) {
    const descriptions={north:'Hồ nước tĩnh, phố nghìn năm và núi đá giữa trời. Một miền Bắc nhiều lớp cảnh quan và ký ức.',central:'Từ kinh thành, phố cổ đến rừng thông cao nguyên. Những vùng đất nối nhau bằng di sản và hương vị.',south:'Nhịp sống đô thị đầy năng lượng, rồi chậm lại bên những bờ biển phía nam.'};
    $('#region-results').innerHTML=`<div class="region-description"><span>${regions[region]}</span><p>${descriptions[region]}</p></div><div class="region-cards">${DATA.destinations.filter(d=>d.region===region).map((d,i)=>card(d,i)).join('')}</div>`;
    $$('[data-country-region]').forEach(b=>{b.classList.toggle('active',b.dataset.countryRegion===region);b.setAttribute('aria-pressed',b.dataset.countryRegion===region)});
  }
  function setInterest(interest) {
    const visuals={nature:['dalat-pines','ĐÀ LẠT / NATURE & STILLNESS'],culture:['hue-citadel','HUẾ / STORIES & HERITAGE'],food:['hoian-street','HỘI AN / LOCAL LIFE & FLAVOURS'],relax:['phuquoc-beach','PHÚ QUỐC / SLOW DAYS'],adventure:['ninh-binh','NINH BÌNH / BEYOND THE FAMILIAR'],photo:['halong-bay','HẠ LONG / FRAME THE MOMENT']};
    const [img,label]=visuals[interest]; const im=$('#interest-image'); im.src=`assets/${img}.jpg`; im.srcset=imageSet(img); im.alt=label; $('#interest-photo-label').textContent=label;
    $$('[data-interest]').forEach(b=>{b.classList.toggle('active',b.dataset.interest===interest);b.setAttribute('aria-selected',b.dataset.interest===interest);b.tabIndex=b.dataset.interest===interest?0:-1;});
    const panel=$('#interest-matches'); panel.setAttribute('aria-labelledby','interest-'+interest); panel.innerHTML=`<p>Những miền đất dành cho bạn</p><div>${DATA.destinations.filter(d=>d.tags.includes(interest)).slice(0,4).map(d=>`<a href="${href(d)}">${d.name} ↗</a>`).join('')}</div>`;
  }
  function refreshFavorites() {
    $$('.saved-count').forEach(el=>el.textContent=favorites.length);
    $$('[data-favorite]').forEach(b=>{const id=b.dataset.favorite, d=DATA.destinations.find(x=>x.id===id),saved=favorites.includes(id);b.setAttribute('aria-pressed',saved);b.setAttribute('aria-label',(saved?'Bỏ lưu ':'Lưu ')+d.name);b.classList.toggle('is-saved',saved);b.textContent=b.classList.contains('inline-favorite')?(saved?'♥ Đã lưu điểm đến':'♡ Lưu điểm đến'):(saved?'♥':'♡')});
  }
  function refreshPlannerChoices() {
    const d=DATA.destinations.find(d=>d.id===$('#planner-destination').value);
    $('#planner-context').textContent=`${d.name} / GLOBEA TRAVEL NOTES`;
    $('#planner-photo').src=`assets/${d.image}.jpg`; $('#planner-photo').srcset=imageSet(d.image); $('#planner-photo').alt=d.name;
    $('#planner-places').innerHTML=d.places.map(([name],i)=>`<label><input type="checkbox" name="places" value="${i}"><span>${name}</span></label>`).join('');
    $('#planner-foods').innerHTML=d.foods.map(([name],i)=>`<label><input type="checkbox" name="foods" value="${i}"><span>${name}</span></label>`).join('');
  }
  function openPlanner(id) {
    if (id && $('#planner-destination').value!==id) { $('#planner-destination').value=id;refreshPlannerChoices();showStep(0); }
    focusReturn=document.activeElement;
    closeMenu();
    if(!dialog.open) dialog.showModal();
    dialog.appendChild($('#toast'));
    document.body.classList.add('modal-open');
    if(!$('#planner-result').hidden) $('#planner-result').focus(); else $('#planner-destination').focus({preventScroll:true});
  }
  function closePlanner() { dialog.close(); document.body.appendChild($('#toast')); document.body.classList.remove('modal-open'); focusReturn?.focus({preventScroll:true}); }
  function showStep(step) {
    activeStep=step;
    $('#planner-form').hidden=false;$('#planner-result').hidden=true;$('.planner-stepper').hidden=false;
    $$('.form-step').forEach((s,i)=>s.hidden=i!==step);
    $$('.planner-stepper>span').forEach((s,i)=>{s.classList.toggle('active',i===step);s.classList.toggle('done',i<step)});
    $('#planner-back').hidden=step===0;$('#planner-next').hidden=step===2;$('#planner-generate').hidden=step!==2;$('.drawer-foot').hidden=false;
    $('#form-error').hidden=true;$('.drawer-content').scrollTop=0;
  }
  function validateStep() { const fields=$$('input,select,textarea',$(`.form-step[data-step="${activeStep}"]`)); for(const f of fields) if(!f.checkValidity()){f.reportValidity();return false;}return true; }
  function formOptions() { const f=new FormData(form);return {destination:f.get('destination'),days:Number(f.get('days')),people:Number(f.get('people')),date:f.get('date'),companion:f.get('companion'),interests:f.getAll('interests'),places:f.getAll('places').map(Number),foods:f.getAll('foods').map(Number),budget:Number(f.get('budget'))||0,budgetBasis:f.get('budgetBasis'),style:f.get('style'),stay:f.get('stay'),transport:f.get('transport'),pace:f.get('pace'),notes:String(f.get('notes')||'').trim()}; }

  function generatePlan(o) {
    const d=DATA.destinations.find(d=>d.id===o.destination);
    const capacity=o.pace==='slow'?1:o.pace==='active'?3:2;
    if(o.places.length>o.days*capacity) throw new Error(`Bạn chọn ${o.places.length} điểm, nhưng nhịp đi này có ${o.days*capacity} khoảng tham quan. Hãy tăng số ngày, tăng nhịp độ hoặc chọn ít điểm hơn.`);
    let remaining=d.places.map((p,i)=>({p,i,score:(o.places.includes(i)?100:0)+p[3].filter(t=>o.interests.includes(t)).length*8}));
    const foodOrder=[...new Set([...o.foods,...d.foods.map((_,i)=>i)])];
    const dayPlans=[];
    for(let day=0;day<o.days;day++) {
      let picked=[];
      for(let n=0;n<capacity&&remaining.length;n++) {
        const group=picked[0]?.p[4];
        const futureSlots=(o.days-day-1)*capacity;
        const mandatory=remaining.filter(x=>o.places.includes(x.i)).length;
        const mustChoose=mandatory>futureSlots+(capacity-n-1);
        const score=x=>x.score+(group&&x.p[4]===group&&!mustChoose?120:0)+(mustChoose&&o.places.includes(x.i)?1000:0);
        remaining.sort((a,b)=>score(b)-score(a)||((a.i+(o.variant||0))%d.places.length)-((b.i+(o.variant||0))%d.places.length));
        const next=remaining.shift();picked.push(next);
      }
      const placeSlot=(item,time,label)=>item?{time,label,title:item.p[0],description:item.p[2],area:item.p[1],type:'place'}:{time,label,title:'Khoảng trống cho riêng bạn',description:'Nghỉ ngơi, dạo khu lưu trú hoặc trở lại góc yêu thích. Bạn có thể tự điều chỉnh theo thời tiết.',area:'Theo nhịp của bạn',type:'rest'};
      const food=d.foods[foodOrder[day%foodOrder.length]], dinner=d.foods[foodOrder[(day+1)%foodOrder.length]];
      const slots=[placeSlot(picked[0],'08:30','Buổi sáng'),{time:'12:00',label:'Bữa trưa',title:food[0],description:food[1]+' Dành thời gian nghỉ sau bữa ăn.',area:'Chọn quán gần điểm tham quan',type:'food'},placeSlot(picked[1],o.pace==='slow'?'15:30':'14:30','Buổi chiều'),picked[2]?placeSlot(picked[2],'17:00','Chiều muộn'):{time:'18:30',label:'Buổi tối',title:dinner[0]+' & một buổi tối thư thả',description:dinner[1]+' Chọn giờ về phù hợp sức khỏe và lịch ngày mai.',area:'Gần khu lưu trú',type:'food'}];
      dayPlans.push({title:picked[0]?.p[4]==='bay'?'Một ngày trên vịnh':picked.length?picked[0].p[0]:'Sống chậm ở '+d.name,slots});
    }
    const lodging=o.style==='luxury'?.5:o.style==='budget'?.3:.4;
    const lodgingNames={Hostel:['trung tâm','phố cổ','Tam Cốc'],Homestay:['Cẩm Châu','Tam Cốc','ven trung tâm','Kim Long','Ông Lang'],Resort:['An Bàng','Tuyền Lâm','ven đô','Bãi Trường','Bãi Cháy'],'Khách sạn':['trung tâm','Hoàn Kiếm','Bãi Cháy','Dương Đông']};
    const stay=d.stays.find(([n,t])=>(lodgingNames[o.stay]||[]).some(k=>norm(n+' '+t).includes(norm(k))))||d.stays[0];
    return {version:1,destination:d.id,created:new Date().toISOString(),options:o,days:dayPlans,stay,budgetShares:[['Lưu trú',lodging],['Ăn uống',.25],['Di chuyển & trải nghiệm',1-lodging-.35],['Dự phòng',.1]]};
  }
  function dayDate(index) { if(!plan.options.date) return '';const date=new Date(plan.options.date+'T12:00:00');date.setDate(date.getDate()+index);return new Intl.DateTimeFormat('vi-VN',{day:'numeric',month:'long'}).format(date); }
  function activityHTML(slot,index,day,editable=true) { return `<article class="itinerary-activity"><div class="activity-time"><time>${slot.time}</time><small>${slot.label}</small></div><div><h4>${escape(slot.title)}</h4><p>${escape(slot.description)}</p><span>${escape(slot.area)}</span></div>${editable?`<button class="remove-activity" data-remove="${index}" data-day="${day}" aria-label="Xóa hoạt động ${escape(slot.title)}">×</button>`:''}</article>`; }
  function budgetHTML() {
    const o=plan.options, total=o.budget*(o.budgetBasis==='person'?o.people:1);
    if(!total)return '<p class="plan-note">Bạn chưa đặt ngân sách. Hãy xác nhận giá dịch vụ thực tế trước khi đặt.</p>';
    let used=0;
    return `<div class="budget-summary"><h4>Phân bổ ngân sách bạn đặt</h4><strong>${money(total)} <small>/ cả nhóm</small></strong><div>${plan.budgetShares.map(([name,pct],i)=>{const amount=i===plan.budgetShares.length-1?total-used:Math.floor(total*pct);used+=amount;return `<span>${name}<b>${money(amount)}</b></span>`}).join('')}</div><p>Phân bổ tham khảo từ ngân sách bạn nhập, không phải báo giá hoặc ước tính giá thị trường. Chưa xác nhận vé, dịch vụ, thuế hay chi phí di chuyển đến điểm đến.</p></div>`;
  }
  function renderPlan() {
    const d=DATA.destinations.find(d=>d.id===plan.destination),o=plan.options;
    $('#planner-form').hidden=true;$('.planner-stepper').hidden=true;$('.drawer-foot').hidden=true;
    $('#planner-context').textContent=`${d.name} / HÀNH TRÌNH CỦA BẠN`;
    const result=$('#planner-result');result.hidden=false;result.tabIndex=-1;
    result.innerHTML=`<div class="result-heading"><span class="eyebrow">GLOBEA / YOUR TRAVEL NOTES</span><h3>Hẹn một ngày<br><em>ở ${d.name}.</em></h3><p>${o.days} ngày · ${o.people} người · ${o.stay}</p><span>${o.date?'Bắt đầu '+dayDate(0):'Ngày khởi hành: tùy bạn'} · ${escape(o.transport)}</span></div><div class="plan-actions"><button data-save-plan>♡ Lưu lịch trình</button><button data-edit-plan>Chỉnh sửa</button><button data-regenerate>Tạo lại</button><button data-print>In / PDF ↗</button></div><div class="day-tabs" role="tablist" aria-label="Chọn ngày hành trình">${plan.days.map((d,i)=>`<button role="tab" id="day-tab-${i}" aria-controls="day-panel" aria-selected="${i===selectedDay}" tabindex="${i===selectedDay?0:-1}" class="${i===selectedDay?'active':''}" data-day-tab="${i}">Ngày ${i+1}</button>`).join('')}</div><div class="day-panel" id="day-panel" role="tabpanel" aria-labelledby="day-tab-${selectedDay}" tabindex="0"><small>${dayDate(selectedDay)}</small><h4 class="day-heading">${escape(plan.days[selectedDay].title)}</h4>${plan.days[selectedDay].slots.length?plan.days[selectedDay].slots.map((s,i)=>activityHTML(s,i,selectedDay)).join(''):'<p class="plan-note">Ngày trống — dành cho những điều bất ngờ. Chỉnh sửa hoặc tạo lại để thêm hoạt động.</p>'}</div><div class="plan-stay"><span class="eyebrow">MỘT NƠI ĐỂ TRỞ VỀ</span><h4>${escape(plan.stay[0])}</h4><p>${escape(plan.stay[1])}</p><small>Ưu tiên của bạn: ${escape(o.stay)}. Xác nhận lựa chọn và giá thực tế trước khi đặt.</small></div>${budgetHTML()}${o.foods.length?`<div class="plan-note"><strong>Hương vị đã chọn</strong><p>${o.foods.map(i=>escape(d.foods[i]?.[0]||'')).join(' · ')}. Có thể dùng cho bữa sáng, trưa hoặc tối tùy lịch.</p></div>`:''}${o.notes?`<div class="plan-note"><strong>Ghi chú riêng của bạn</strong><p>${escape(o.notes)}</p></div>`:''}<div class="plan-note"><strong>Một vài điều trước khi lên đường</strong><p>${d.tips[0][1]}</p><p>Giờ là gợi ý linh hoạt. ${d.id==='ha-long'?'Các điểm trên vịnh phải theo tuyến và giờ của tàu được cấp phép; đây không phải lịch tàu đã xác nhận. ':''}Kiểm tra giờ mở cửa, quãng đường và thời tiết. ${o.companion==='family'?'Đi cùng gia đình: thêm khoảng nghỉ và chọn hoạt động phù hợp từng thành viên. ':''}${o.transport==='Xe máy'?'Chỉ chọn xe máy khi có giấy phép phù hợp và quen đường địa phương. ':''}Bạn có thể bỏ bớt hoạt động để phù hợp nhịp đi.</p><small>Lịch trình gợi ý theo quy tắc từ dữ liệu có sẵn. Không phải dịch vụ đặt tour.</small></div>`;
    updatePrint();
  }
  function updatePrint() {
    if(!plan)return;
    const d=DATA.destinations.find(d=>d.id===plan.destination);
    $('#print-plan').innerHTML=`<header><span>GLOBEA / TRAVEL NOTES</span><h1>${d.name} · Hành trình của bạn</h1><p>${plan.options.days} ngày · ${plan.options.people} người · ${escape(plan.options.transport)} · ${escape(plan.options.stay)}</p></header>${plan.days.map((d,i)=>`<section><h2>Ngày ${i+1} ${dayDate(i)} · ${escape(d.title)}</h2>${d.slots.map((s,n)=>activityHTML(s,n,i,false)).join('')}</section>`).join('')}<section><h2>Lưu trú · ${escape(plan.stay[0])}</h2><p>${escape(plan.stay[1])}</p>${budgetHTML()}${plan.options.notes?`<h3>Ghi chú</h3><p>${escape(plan.options.notes)}</p>`:''}<p>${d.tips.map(t=>escape(t[1])).join(' ')}</p><p>Giờ và hoạt động là gợi ý; kiểm tra thời tiết, lịch mở cửa và tuyến trước khi đi. Lịch trình tạo từ dữ liệu có sẵn, không phải dịch vụ đã đặt.</p></section>`;
  }
  function editPlan() {
    const o=plan.options;$('#planner-destination').value=plan.destination;refreshPlannerChoices();
    Object.entries(o).forEach(([key,value])=>{if(Array.isArray(value))$$(`[name="${key}"]`,form).forEach(el=>el.checked=value.map(String).includes(el.value));else{const el=$(`[name="${key}"]`,form);if(el?.type==='radio')$$(`[name="${key}"]`,form).forEach(r=>r.checked=r.value===String(value));else if(el)el.value=value;}});
    showStep(0);
  }
  function openLightbox(id,index) { const d=DATA.destinations.find(d=>d.id===id); lightboxItems=d.gallery.map(im=>({image:im,alt:d.name}));lightboxIndex=index;focusReturn=document.activeElement;showLightbox();lightbox.showModal();document.body.classList.add('modal-open'); }
  function showLightbox() { const item=lightboxItems[lightboxIndex];$('#lightbox img').src=`assets/${item.image}.jpg`;$('#lightbox img').alt=item.alt+' · Ảnh '+(lightboxIndex+1);$('#lightbox figcaption').textContent=`${item.alt} / ${lightboxIndex+1} — ${lightboxItems.length}`;$('.lightbox-prev').hidden=$('.lightbox-next').hidden=lightboxItems.length===1; }
  function closeMenu() { $('#mobile-menu').hidden=true;$('.menu-toggle').setAttribute('aria-expanded','false');$('.menu-toggle').setAttribute('aria-label','Mở menu');document.body.classList.remove('menu-open'); }

  document.addEventListener('click',e=>{
    const b=e.target.closest('button,a');if(!b)return;
    if(b.matches('[data-open-planner]'))openPlanner(b.dataset.plannerDestination);
    if(b.matches('[data-close-planner]'))closePlanner();
    if(b.matches('.menu-toggle')){const open=$('#mobile-menu').hidden;$('#mobile-menu').hidden=!open;b.setAttribute('aria-expanded',open);b.setAttribute('aria-label',open?'Đóng menu':'Mở menu');document.body.classList.toggle('menu-open',open);}
    if(b.closest('#mobile-menu')&&b.tagName==='A')closeMenu();
    if(b.matches('[data-favorite]')){const id=b.dataset.favorite;favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];const saved=write('globea-favorites-v1',favorites);refreshFavorites();if(state.savedOnly)renderDestinations();if(saved)toast(favorites.includes(id)?'Đã lưu một miền đất vào danh sách của bạn.':'Đã bỏ lưu điểm đến.');}
    if(b.matches('[data-region]')){state.region=b.dataset.region;renderDestinations();}
    if(b.matches('.filter-saved')){state.savedOnly=!state.savedOnly;renderDestinations();}
    if(b.matches('.saved-toggle')){if(page==='home'){state.savedOnly=true;state.query='';state.interest='all';state.region='all';$('#destination-query').value='';renderDestinations();$('#diem-den').scrollIntoView({behavior:reduced.matches?'instant':'smooth'});}else location.href='index.html?saved=1#diem-den';}
    if(b.matches('[data-clear-filters]')){Object.assign(state,{query:'',region:'all',interest:'all',savedOnly:false});$('#destination-query').value='';renderDestinations();}
    if(b.matches('[data-clear-interest]')){state.interest='all';renderDestinations();}
    if(b.matches('[data-interest]'))setInterest(b.dataset.interest);
    if(b.matches('[data-country-region]'))renderRegion(b.dataset.countryRegion);
    if(b.matches('[data-history]')){const i=Number(b.dataset.history);$$('[data-history]').forEach(x=>{const active=x===b;x.classList.toggle('active',active);x.setAttribute('aria-selected',active);x.tabIndex=active?0:-1});$('#history-panel').setAttribute('aria-labelledby',b.id);$('#history-panel').innerHTML=`<h3>${current.timeline[i][1]}</h3><p>${current.timeline[i][2]}</p>`;}
    if(b.matches('[data-add-place],[data-add-food]')){openPlanner(current.id);const name=b.hasAttribute('data-add-place')?'places':'foods';const value=b.dataset.addPlace??b.dataset.addFood;$(`[name="${name}"][value="${value}"]`,form).checked=true;showStep(1);toast('Đã thêm lựa chọn vào chuyến đi.');}
    if(b.matches('#planner-next')&&validateStep()){showStep(activeStep+1);$('.form-step:not([hidden]) h3').tabIndex=-1;$('.form-step:not([hidden]) h3').focus();}
    if(b.matches('#planner-back'))showStep(activeStep-1);
    if(b.matches('[data-save-plan]')){if(write('globea-plan-v1',plan)){toast('Đã lưu lịch trình trên trình duyệt này.');b.textContent='♥ Đã lưu';$('#load-plan').hidden=false;}}
    if(b.matches('#load-plan')){plan=read('globea-plan-v1',null);if(validPlan(plan)){selectedDay=0;renderPlan();}else toast('Chưa có lịch trình hợp lệ được lưu.');}
    if(b.matches('[data-edit-plan]'))editPlan();
    if(b.matches('[data-regenerate]')){plan=generatePlan({...plan.options,variant:(plan.options.variant||0)+1});selectedDay=0;renderPlan();toast('Đã tạo lại lịch trình từ các lựa chọn của bạn.');}
    if(b.matches('[data-day-tab]')){selectedDay=Number(b.dataset.dayTab);renderPlan();$(`#day-tab-${selectedDay}`).focus({preventScroll:true});}
    if(b.matches('[data-remove]')){plan.days[Number(b.dataset.day)].slots.splice(Number(b.dataset.remove),1);renderPlan();toast('Đã xóa hoạt động. Lưu lại để cập nhật bản lưu.');}
    if(b.matches('[data-print]')){updatePrint();window.print();}
    if(b.matches('[data-gallery]'))openLightbox(b.dataset.gallery,Number(b.dataset.index));
    if(b.matches('.lightbox-close'))lightbox.close();
    if(b.matches('.lightbox-prev,.lightbox-next')){lightboxIndex=(lightboxIndex+(b.matches('.lightbox-next')?1:-1)+lightboxItems.length)%lightboxItems.length;showLightbox();}
    if(b.matches('#back-top'))window.scrollTo({top:0,behavior:reduced.matches?'instant':'smooth'});
    if(b.matches('[data-contact]'))location.href='nguon.html#thong-tin-lien-he';
  });
  $('#hero-search')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);state.query=String(f.get('destination'));state.interest=f.get('interest')!=='all'?f.get('interest'):f.get('pace');state.region='all';state.savedOnly=false;$('#destination-query').value=state.query;renderDestinations();$('#diem-den').scrollIntoView({behavior:reduced.matches?'instant':'smooth'});});
  $('#destination-query')?.addEventListener('input',e=>{state.query=e.target.value;renderDestinations();});
  $('#planner-destination').addEventListener('change',()=>{refreshPlannerChoices();$('#form-error').hidden=true;});
  form.addEventListener('submit',e=>{e.preventDefault();if(!validateStep())return;try{plan=generatePlan(formOptions());selectedDay=0;renderPlan();$('.drawer-content').scrollTop=0;toast('Hành trình của bạn đã sẵn sàng.');}catch(err){$('#form-error').textContent=err.message;$('#form-error').hidden=false;}});
  dialog.addEventListener('click',e=>{if(e.target===dialog&&e.clientX<dialog.getBoundingClientRect().left)closePlanner();});
  dialog.addEventListener('cancel',e=>{e.preventDefault();closePlanner();});
  lightbox.addEventListener('click',e=>{if(e.target===lightbox)lightbox.close();});
  lightbox.addEventListener('close',()=>{document.body.classList.remove('modal-open');focusReturn?.focus({preventScroll:true});});
  document.addEventListener('keydown',e=>{
    if(e.key==='Escape') {
      if(lightbox.open){e.preventDefault();lightbox.close();}
      else if(dialog.open){e.preventDefault();closePlanner();}
      else if(!$('#mobile-menu').hidden)closeMenu();
    }
    if(lightbox.open&&['ArrowLeft','ArrowRight'].includes(e.key)){lightboxIndex=(lightboxIndex+(e.key==='ArrowRight'?1:-1)+lightboxItems.length)%lightboxItems.length;showLightbox();}
    const list=e.target.closest('[role="tablist"]');if(list&&['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const tabs=$$('[role="tab"]',list),i=tabs.indexOf(e.target),n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[n].focus();tabs[n].click();}
  });
  let scrollPending=false;
  function onScroll(){if(scrollPending)return;scrollPending=true;requestAnimationFrame(()=>{const y=window.scrollY;$('#site-nav').classList.toggle('scrolled',y>45);$('#back-top').classList.toggle('visible',y>650);if(!reduced.matches&&y<innerHeight*1.2){const hero=$('.hero-image img,.place-hero-image img');if(hero&&!(current?.hero==='editorial'))hero.style.transform=`translateY(${Math.min(y*.12,110)}px) scale(1.04)`;}scrollPending=false;});}
  addEventListener('scroll',onScroll,{passive:true});onScroll();
  const observer='IntersectionObserver' in window?new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('revealed');observer.unobserve(entry.target);}}),{threshold:.09}):null;
  $$('.reveal').forEach((el,i)=>{el.style.setProperty('--reveal-delay',`${Math.min(i%3,2)*75}ms`);if(observer&&!reduced.matches){el.classList.add('will-reveal');observer.observe(el);}else el.classList.add('revealed');});
  if(matchMedia('(hover:hover) and (pointer:fine)').matches&&!reduced.matches)$$('[data-tilt]').forEach(el=>{el.addEventListener('pointermove',e=>{const r=el.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;el.style.transform=`perspective(1100px) rotateY(${x*5}deg) rotateX(${-y*5}deg)`;});el.addEventListener('pointerleave',()=>el.style.transform='');});
  document.addEventListener('error',e=>{if(e.target.tagName==='IMG'){e.target.classList.add('image-failed');e.target.alt=e.target.alt||'Ảnh địa điểm tạm thời chưa tải được';}},true);
  const url=new URL(location.href);if(page==='home'&&url.searchParams.get('saved')){state.savedOnly=true;renderDestinations();}
  if(location.hash)setTimeout(()=>{const el=document.getElementById(decodeURIComponent(location.hash.slice(1)));el?.scrollIntoView({behavior:'instant'});},100);
  // Pure planner API supports repeatable verification without external services.
  window.GlobeaPlanner=Object.freeze({generate:generatePlan,normalize:norm});
})();
